import { readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { LOCALES } from '../src/db/schema'
import { readLanding } from './landing'
import { lit } from './sql'

type Text = { name: string; subtitle: string }
const dir = import.meta.dir
const catalog = JSON.parse(readFileSync(join(dir, 'catalog.json'), 'utf8')) as {
  categories: ({ slug: string } & Record<string, Text>)[]
}
const landing = readLanding(catalog.categories.map((c) => c.slug))

const statements = [
  '-- Generated by seed/sync-texts.ts. Do not edit by hand.',
  ...catalog.categories.flatMap((c) =>
    LOCALES.map((locale) => {
      const t = landing.categories[c.slug]![locale]!
      return `UPDATE category_translations SET name = ${lit(c[locale]!.name)}, subtitle = ${lit(c[locale]!.subtitle)}, description = ${lit(t.description)}, seo_title = ${lit(t.seoTitle)}, seo_description = ${lit(t.seoDescription)} WHERE locale = ${lit(locale)} AND category_id = (SELECT id FROM categories WHERE slug = ${lit(c.slug)});`
    }),
  ),
]

writeFileSync(join(dir, 'sync-texts.sql'), `${statements.join('\n')}\n`)
console.log(`sync-texts.sql written: ${statements.length - 1} statements`)
